import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import '../chat/chat_screen.dart';import 'product_service.dart';class ProductDetailScreen extends StatelessWidget{final String productId;const ProductDetailScreen({super.key,required this.productId});@override Widget build(BuildContext c){final uid=FirebaseAuth.instance.currentUser!.uid;final fav=FirebaseFirestore.instance.collection('users').doc(uid).collection('favorites').doc(productId);return StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('products').doc(productId).snapshots(),builder:(c,s){if(!s.hasData)return const Scaffold(body:Center(child:CircularProgressIndicator()));final x=s.data!.data();if(x==null)return const Scaffold(body:Center(child:Text('Iklan tidak ditemukan')));final imgs=List<String>.from(x['imageUrls']??[x['imageUrl']??'']);return Scaffold(appBar:AppBar(title:const Text('Detail Iklan'),actions:[StreamBuilder<DocumentSnapshot>(stream:fav.snapshots(),builder:(c,f)=>IconButton(icon:Icon(f.data?.exists==true?Icons.favorite:Icons.favorite_border,color:f.data?.exists==true?Colors.red:null),onPressed:()async{if(f.data?.exists==true){await fav.delete();}else{await fav.set({'title':x['title'],'price':x['price'],'imageUrl':x['imageUrl']});}}))]),body:ListView(padding:const EdgeInsets.all(20),children:[SizedBox(height:260,child:PageView(children:imgs.where((e)=>e.isNotEmpty).map((u)=>Image.network(u,fit:BoxFit.cover)).toList())),const SizedBox(height:16),Text(x['title']??'',style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),Text('Rp '+(x['price']??0).toString(),style:const TextStyle(fontSize:23,color:Color(0xFF0866FF),fontWeight:FontWeight.bold)),Text('📍 '+(x['locationName']??'Lokasi penjual')),const Divider(height:32),const Text('Deskripsi',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),Text(x['description']??''),OutlinedButton.icon(onPressed:()=>ProductService().report(productId,'Dilaporkan pengguna'),icon:const Icon(Icons.flag_outlined),label:const Text('Laporkan iklan')),FilledButton.icon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ChatScreen(sellerId:x['sellerId']??'',sellerName:x['sellerName']??'Penjual',productId:productId,productTitle:x['title']??''))),icon:const Icon(Icons.chat),label:const Text('Chat Penjual'))]));});}}